/* Brief, source-checked chapter explanations. Full proofs remain in the reader. */
window.createTextbookDigest=function({D,escape,md,heading,questionLabel}){
 const digest=D.textbookCondensed||{},chapters=digest.chapters||[],byChapter=new Map(chapters.map(c=>[String(c.chapter),c]));
 const primary=new Set(['2','4','7','9','10']);
 const label=c=>c.chapter==='S'?'补充专题':'第'+c.chapter+'章';
 const priority=c=>primary.has(c.chapter)?'优先主线':c.chapter==='S'?'近年补充':c.chapter==='11'?'结构训练':'配套基础';
 const url=c=>'#digest?chapter='+encodeURIComponent(c.chapter);
 const sourceLabel=s=>`${s.label} · 书页${s.printFrom}${s.printTo!==s.printFrom?'–'+s.printTo:''} / PDF${s.pdfFrom}${s.pdfTo!==s.pdfFrom?'–'+s.pdfTo:''}`;
 function chapter(c,continuous=false){
  const i=chapters.indexOf(c);
  return `<article class="condensed-chapter" id="digest-${escape(c.id)}"><header class="condensed-chapter-head"><div><span class="digest-chapter-label">${label(c)}</span><span class="digest-priority ${primary.has(c.chapter)?'is-core':''}">${priority(c)}</span></div><h1>${escape(c.title)}</h1><div class="digest-core">${md(c.coreIdea)}</div></header><div class="condensed-body"><section class="digest-essentials"><h2>抓住这几条</h2>${c.essentials.map((e,n)=>`<section class="digest-essential"><h3><span>${n+1}</span>${escape(e.title)}</h3><div>${md(e.explanation)}</div>${e.formula?`<div class="digest-formula">${md(e.formula)}</div>`:''}</section>`).join('')}</section><section class="digest-first-steps"><h2>看到题目，先做什么</h2>${c.firstSteps.map(s=>`<div><strong>${escape(s.trigger)}</strong><div class="digest-step-action">${md(s.action)}</div></div>`).join('')}</section><section class="digest-mini-example"><h2>${escape(c.miniExample.title)}</h2>${md(c.miniExample.body)}</section><section class="digest-pitfalls"><h2>这两处最容易混</h2><ul>${c.pitfalls.map(p=>`<li>${md(p)}</li>`).join('')}</ul></section><section class="digest-selfcheck"><h2>检查是否理解</h2>${md(c.selfCheck.question)}<details><summary>查看答案与理由</summary>${md(c.selfCheck.answer)}</details></section><section class="digest-example-links"><h2>用真题检验</h2><div class="inline-actions">${c.examIds.map(id=>`<button data-action="open" data-id="${escape(id)}">${escape(questionLabel(id))} →</button>`).join('')}</div><div class="inline-actions digest-related"><a href="#reference?chapter=${escape(c.chapter)}">本章公式与原书表格 →</a><a href="#papers?chapter=${escape(c.chapter)}">全部同章真题 →</a></div></section><details class="digest-sources"><summary>原书依据与回看位置</summary><p>本章提要按原书正文与典型例题独立整理；式子的适用条件与例题边界随正文保留。</p>${c.sourceSpans.map(s=>`<p>${escape(sourceLabel(s))}</p>`).join('')}<div class="inline-actions">${c.bookLinks.map(b=>`<button data-action="open-book" data-pdf="${b.pdfPage}">${escape(b.label)} · PDF${b.pdfPage} →</button>`).join('')}</div></details></div></article>${continuous?'':`<div class="digest-pagination">${i?`<a class="button" href="${url(chapters[i-1])}">← ${label(chapters[i-1])}</a>`:'<span></span>'}<a href="#digest">回到提要目录</a>${i<chapters.length-1?`<a class="button" href="${url(chapters[i+1])}">${label(chapters[i+1])} →</a>`:'<span></span>'}</div>`}`;
 }
 return function render(p){
  const selected=byChapter.get(p.get('chapter'));
  const toolbar=`<div class="digest-toolbar"><a class="button" href="#digest">← 精读提要目录</a><a class="button" href="downloads/textbook-condensed.pdf" download>下载精简 PDF ↓</a><a href="#book">回看原书</a></div>`;
  if(selected)return toolbar+chapter(selected);
  if(p.get('view')==='all')return toolbar+heading('原书精读 / 连续阅读','把整本书串成一条主线','每章保留核心结论、第一步、小例子与易错点。需要完整证明时，从章末链接回到原书。')+chapters.map(c=>chapter(c,true)).join('');
  return heading('原书精读 / 中大备考精简版','先读清主线，再用真题检验','按原书11章正文梳理，附正交投影补充。每章只留需要理解和能用来解题的内容，原书与长表按需回看。')+`<section class="condensed-intro"><div><h2>读书时先知道自己在找什么</h2>${md(digest.readingAdvice||'先抓频谱与系统两条主线，再用真题查缺补漏。')}</div><div class="condensed-intro-actions"><a class="button primary" href="${url(byChapter.get('2')||chapters[0])}">从 LTI 主线开始 →</a><a class="button" href="downloads/textbook-condensed.pdf" download>下载精简 PDF ↓</a><a href="#digest?view=all">连续阅读全部提要 →</a></div></section><div class="digest-reading-paths"><section><span>频谱主线</span><h3>级数与变换 → 幅相 → 抽样与调制</h3><div>${['3','4','5','6','7','8'].map(id=>`<a href="${url(byChapter.get(id))}">第${id}章</a>`).join('')}</div></section><section><span>系统主线</span><h3>卷积与响应 → ROC与初态 → 闭环</h3><div>${['1','2','9','10','11'].map(id=>`<a href="${url(byChapter.get(id))}">第${id}章</a>`).join('')}</div></section></div><div class="section-head"><h2>逐章提要</h2><a href="#reference">需要时查完整公式表 →</a></div><div class="digest-chapter-grid">${chapters.map(c=>{const stats=D.chapters.find(s=>s.chapter===c.chapter);return `<a class="digest-index-card ${primary.has(c.chapter)?'is-core':''}" href="${url(c)}"><div><span class="digest-chapter-label">${label(c)}</span><span class="digest-priority ${primary.has(c.chapter)?'is-core':''}">${priority(c)}</span></div><h3>${escape(c.title)}</h3><div class="digest-index-summary">${md(c.coreIdea)}</div>${stats?`<small>已见真题涉及${stats.year_count}年 · 近五年${stats.recent_years}年</small>`:''}<strong>读精简提要 →</strong></a>`;}).join('')}</div><p class="digest-scope-note">覆盖年份用于安排复习顺序，综合题会跨章统计，不代表分值比例。精读范围与原书页码在每章末尾列出。</p><div class="digest-footer-links"><a href="#book">整本原书高清阅读 →</a><a href="#reference">53张公式与方法速查 →</a><a href="#downloads">PDF与离线安装包 →</a></div>`;
 };
};
